}.sbd-page .sbd *{box-sizing:border-box;margin:0;padding:0}.sbd-page .sbd{font-family:'Cabin','Segoe UI',Arial,sans-serif;color:var(--ink);line-height:1.62;background:var(--white);font-size:17px;scroll-behavior:smooth;-webkit-font-smoothing:antialiased}.sbd-page .sbd h1,.sbd-page .sbd h2,.sbd-page .sbd h3,.sbd-page .sbd h4{font-family:Arial,Helvetica,sans-serif;font-weight:800;color:var(--slate);line-height:1.12;letter-spacing:-.015em}.sbd-page .sbd h1{font-size:clamp(33px,5vw,60px)}.sbd-page .sbd h2{font-size:clamp(27px,3.5vw,42px)}.sbd-page .sbd h3{font-size:clamp(18px,2vw,22px)}.sbd-page .sbd h4{font-size:17px}.sbd-page .sbd p{margin:0 0 1rem}.sbd-page .sbd p:last-child{margin-bottom:0}.sbd-page .sbd a{color:var(--blue-deep);text-decoration:underline;text-underline-offset:2px}.sbd-page .sbd a:hover{color:var(--navy)}.sbd-page .sbd img{max-width:100%;display:block;height:auto}.sbd-page .sbd ul{list-style:none}.sbd-page .sbd svg{display:block}.sbd-page .sbd :focus-visible{outline:3px solid var(--gold);outline-offset:3px;border-radius:5px}.sbd-page .wrap{max-width:1200px;margin:0 auto;padding:0 22px;position:relative}.sbd-page .ico{width:1em;height:1em;fill:currentColor;flex:0 0 auto}.sbd-page .section{padding:86px 0;position:relative;overflow:hidden}.sbd-page .s-white{background:var(--white)}.sbd-page .s-light{background:var(--light)}.sbd-page .s-navy{background:var(--navy);color:#dfe7ed}.sbd-page .s-navy h2,.sbd-page .s-navy h3,.sbd-page .s-navy h4{color:#fff}.sbd-page .s-navy::before{content:"";position:absolute;inset:0;pointer-events:none;background-image:var(--m-rings);background-repeat:no-repeat;background-position:right -190px top -150px}.sbd-page .section > .wrap{position:relative;z-index:2}.sbd-page .eyebrow{display:inline-flex;align-items:center;gap:.55rem;font-weight:700;text-transform:uppercase;letter-spacing:.11em;font-size:12.5px;color:var(--blue-deep);margin-bottom:.7rem}.sbd-page .eyebrow::before{content:"";width:24px;height:2px;background:var(--blue